from fastapi import FastAPI, UploadFile, File
from fastapi.responses import HTMLResponse, JSONResponse
import cv2, numpy as np, sqlite3, uuid
from pathlib import Path
from datetime import datetime
app=FastAPI(title='PokémonGrader Luxe')
DB=Path('pokemongrader.db')
def analyze(data):
 a=np.frombuffer(data,np.uint8); im=cv2.imdecode(a,cv2.IMREAD_COLOR)
 if im is None:return None
 h,w=im.shape[:2]; g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY); e=cv2.Canny(cv2.GaussianBlur(g,(5,5),0),60,160)
 cs,_=cv2.findContours(e,cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_SIMPLE); c=max(cs,key=cv2.contourArea) if cs else None
 cov=min(1,(cv2.contourArea(c)/(w*h)) if c is not None else 0); br=float(np.mean(g)); co=float(np.std(g))
 return {'Centering':max(1,min(10,round(5.8+cov*3.5))),'Corners':max(1,min(10,round(5+co/38))),'Edges':max(1,min(10,round(5.4+cov*3.5))),'Surface':max(1,min(10,round(5.2+br/70)))}
def db():
 c=sqlite3.connect(DB);c.execute('CREATE TABLE IF NOT EXISTS vault(id TEXT,created TEXT,grade REAL,centering INT,corners INT,edges INT,surface INT)');c.commit();return c
@app.get('/',response_class=HTMLResponse)
def home():return HTML
@app.post('/api/grade')
async def grade(front:UploadFile=File(...),back:UploadFile=File(...)):
 a,z=analyze(await front.read()),analyze(await back.read())
 if not a or not z:return JSONResponse({'error':'Ongeldige foto.'},400)
 s={k:round((a[k]+z[k])/2) for k in a};return {'grade':round(sum(s.values())/4,1),'subgrades':s}
@app.post('/api/vault')
async def save(x:dict):
 s=x['subgrades'];c=db();c.execute('INSERT INTO vault VALUES(?,?,?,?,?,?,?)',(str(uuid.uuid4()),datetime.utcnow().isoformat(),x['grade'],s['Centering'],s['Corners'],s['Edges'],s['Surface']));c.commit();c.close();return {'ok':True}

HTML='<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#08070d"><title>PokémonGrader Luxe</title><style>\n:root{--bg:#07070b;--panel:#111118;--line:#292834;--text:#faf9ff;--muted:#9b99a8;--a:#9b6cff;--b:#45d6ff}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% -10%,#9b6cff35,transparent 35%),radial-gradient(circle at 100% 10%,#45d6ff1f,transparent 30%),var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,Inter,system-ui,sans-serif}.app{max-width:620px;margin:auto;padding:18px 18px 105px}.top{display:flex;justify-content:space-between;align-items:center}.brand{font-size:21px;font-weight:900}.logo{display:inline-grid;place-items:center;width:38px;height:38px;margin-right:9px;border-radius:13px;background:linear-gradient(135deg,var(--a),var(--b));vertical-align:middle}.pill{font-size:11px;padding:7px 10px;border:1px solid #fff2;border-radius:99px;color:#d9d3e9}.hero{padding:35px 3px 18px}.ey{color:#b291ff;font-size:11px;font-weight:800;letter-spacing:2px;text-transform:uppercase}h1{font-size:39px;line-height:1.02;letter-spacing:-1.8px;margin:8px 0}.hero p{color:var(--muted);line-height:1.5}.card{background:linear-gradient(145deg,#17151f,#0f0f15);border:1px solid #fff1;border-radius:28px;padding:18px;box-shadow:0 20px 70px #0008}.steps{display:flex;gap:7px;margin-bottom:15px}.step{flex:1;text-align:center;padding:9px 4px;border-radius:12px;background:#fff1;color:#777;font-size:11px;font-weight:800}.active{color:#ddd0ff!important;background:#9b6cff18!important;border:1px solid #9b6cff66}.drop{min-height:245px;border:1px dashed #514e5e;border-radius:22px;display:grid;place-items:center;text-align:center;padding:25px}.drop strong{display:block;font-size:19px}.drop span{display:block;color:var(--muted);font-size:13px;margin-top:7px}.icon{font-size:45px;margin-bottom:8px}input{display:none}.btn{width:100%;padding:16px;border-radius:17px;border:0;font-weight:850;font-size:16px}.primary{color:#fff;background:linear-gradient(135deg,var(--a),#6550ff);box-shadow:0 12px 30px #7258ff55;margin-top:12px}.secondary{color:#eee;background:#fff0;border:1px solid #fff2;margin-top:10px}.preview{display:none;width:100%;max-height:320px;object-fit:contain;border-radius:18px}.muted{color:var(--muted)}#result{display:none}.grade{margin-top:18px;padding:24px;border:1px solid #fff1;border-radius:28px;text-align:center;background:linear-gradient(145deg,#191523,#101016)}.label{font-size:11px;color:var(--muted);letter-spacing:2px;text-transform:uppercase}.num{font-size:78px;font-weight:950;line-height:1;margin:8px;background:linear-gradient(#fff,#b69aff);-webkit-background-clip:text;color:transparent}.badge{display:inline-block;padding:7px 10px;border-radius:99px;background:#8dffbf15;color:#9dffc8;font-size:11px;font-weight:800}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.metric{padding:15px;border-radius:18px;background:#0b0b10;border:1px solid #fff1}.score{font-size:28px;font-weight:900;margin-top:5px}.bar{height:4px;background:#292733;border-radius:99px;margin-top:9px}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--a),var(--b));border-radius:99px}.section{margin-top:20px}.info{padding:15px;border-radius:18px;background:#fff1;border:1px solid #fff1;color:var(--muted);font-size:13px;line-height:1.5}.bottom{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);width:min(580px,calc(100% - 24px));display:flex;justify-content:space-around;padding:9px;background:#14141ddd;border:1px solid #fff2;border-radius:24px;backdrop-filter:blur(18px)}.nav{border:0;background:none;color:#777;padding:6px 12px;font-size:11px;font-weight:800}.nav b{display:block;font-size:20px}.nav.on{color:#d9caff}\n</style></head><body><main class="app"><div class="top"><div class="brand"><span class="logo">⚡</span>PokémonGrader</div><span class="pill">LUXE • BETA</span></div>\n<section class="hero"><div class="ey">AI CARD INTELLIGENCE</div><h1>Grade je kaart.<br>Zie wat ze waard is.</h1><p>Scan de voorkant én achterkant. Beide zijden worden samen beoordeeld voor een transparante conditie-inschatting.</p></section>\n<section class="card"><div class="steps"><div id="st1" class="step active">01 VOORKANT</div><div id="st2" class="step">02 ACHTERKANT</div><div id="st3" class="step">03 GRADE</div></div>\n<div id="frontBox" class="drop"><div><div class="icon">📷</div><strong>Scan de voorkant</strong><span>Kaart volledig in beeld, helder licht.</span><label class="btn secondary" style="display:inline-block;width:auto;margin-top:16px">Foto kiezen<input id="front" type="file" accept="image/*" capture="environment"></label></div></div>\n<img id="fp" class="preview"><div id="backBox" class="drop" style="display:none"><div><div class="icon">🔄</div><strong>Scan de achterkant</strong><span>Zelfde afstand en belichting.</span><label class="btn secondary" style="display:inline-block;width:auto;margin-top:16px">Foto kiezen<input id="back" type="file" accept="image/*" capture="environment"></label></div></div><img id="bp" class="preview">\n<button id="go" class="btn primary" disabled>Doorgaan →</button><div id="status" class="muted" style="font-size:12px;text-align:center;margin-top:9px"></div></section>\n<section id="result"><div class="grade"><div class="label">PokémonGrader score</div><div id="gn" class="num">—</div><div class="badge">✓ VOOR + ACHTERKANT</div></div><div id="metrics" class="grid"></div><div class="section"><div class="info">Dit is een computer-vision prototype en geen officiële PSA-, BGS- of CGC-grade. Controleer zelf whitening, dents, scratches en surface defects.</div></div><button class="btn primary" onclick="save()">✦ Bewaar in Graded Vault</button><button class="btn secondary" onclick="location.reload()">Nieuwe kaart</button></section></main>\n<nav class="bottom"><button class="nav on"><b>⌁</b>Scan</button><button class="nav" onclick="alert(\'Vault komt in de volgende versie.\')"><b>◈</b>Vault</button><button class="nav"><b>◉</b>Collection</button><button class="nav"><b>⚙</b>Settings</button></nav>\n<script>\nlet f,b,stage=1,last=null,$=x=>document.getElementById(x);\nfunction pick(id,preview,front){$(id).onchange=e=>{let x=e.target.files[0];if(!x)return;if(front){f=x;$(\'fp\').src=URL.createObjectURL(x);$(\'fp\').style.display=\'block\';$(\'frontBox\').style.display=\'none\';$(\'st1\').classList.remove(\'active\');$(\'st2\').classList.add(\'active\');$(\'backBox\').style.display=\'grid\';$(\'go\').disabled=true;$(\'status\').textContent=\'Nu de achterkant.\'}else{b=x;$(\'bp\').src=URL.createObjectURL(x);$(\'bp\').style.display=\'block\';$(\'backBox\').style.display=\'none\';$(\'go\').disabled=false;$(\'go\').textContent=\'Grade mijn kaart ✦\'}}};}\npick(\'front\',\'fp\',true);pick(\'back\',\'bp\',false);\n$(\'go\').onclick=async()=>{if(stage===1){stage=2;return}if(!f||!b)return;$(\'go\').disabled=true;$(\'status\').textContent=\'Beide zijden analyseren…\';$(\'st2\').classList.remove(\'active\');$(\'st3\').classList.add(\'active\');let fd=new FormData();fd.append(\'front\',f);fd.append(\'back\',b);let r=await fetch(\'/api/grade\',{method:\'POST\',body:fd}),x=await r.json();if(x.error){$(\'status\').textContent=x.error;$(\'go\').disabled=false;return}last=x;$(\'gn\').textContent=x.grade;let names=[\'Centering\',\'Corners\',\'Edges\',\'Surface\'];$(\'metrics\').innerHTML=names.map(n=>`<div class="metric"><div class="muted">${n}</div><div class="score">${x.subgrades[n]}/10</div><div class="bar"><i style="width:${x.subgrades[n]*10}%"></i></div></div>`).join(\'\');$(\'result\').style.display=\'block\';$(\'status\').textContent=\'Analyse compleet.\';window.scrollTo({top:document.body.scrollHeight,behavior:\'smooth\'})};\nasync function save(){if(!last)return;await fetch(\'/api/vault\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(last)});alert(\'Opgeslagen in Vault ✦\')}\n</script></body></html>'
